UPDATE WH_SYS_ALERT
SET SEVERITY = #{SEVERITY}, MESSAGE = #{MESSAGE}, METRIC_VALUE = #{METRIC_VALUE}, UPDATED_DATE = NOW()
WHERE ALERT_ID = #{ALERT_ID}

UPDATE WH_SYS_ALERT
SET MAIL_SENT_YN = 'Y', NOTIFY_COUNT = NOTIFY_COUNT + 1, LAST_NOTIFIED_DATE = NOW(), UPDATED_DATE = NOW()
WHERE ALERT_ID = #{ALERT_ID}
